import sys
import math

def sum_of_divisors(n):
    s = 1
    temp = n
    p = 2
    while p * p <= temp:
        if temp % p == 0:
            cur = 1
            term = 1
            while temp % p == 0:
                temp //= p
                term *= p
                cur += term
            s *= cur
        p += 1 if p == 2 else 2
    if temp > 1:
        s *= (1 + temp)
    return s

def main():
    A_line = sys.stdin.readline().strip()
    if not A_line:
        return
    A = int(A_line)
    ans = 0
    limit = int(math.isqrt(A))
    for d in range(1, limit + 1):
        if A % d == 0:
            x1 = d
            if sum_of_divisors(x1) == A:
                ans += 1
            x2 = A // d
            if x2 != x1:
                if sum_of_divisors(x2) == A:
                    ans += 1
    print(ans)

if __name__ == "__main__":
    main()

