import sys
import math

def divisor_sum(n):
    s = 1
    temp = n
    p = 2
    while p * p <= temp:
        if temp % p == 0:
            term = 1
            pow_p = 1
            while temp % p == 0:
                temp //= p
                pow_p *= p
                term += pow_p
            s *= term
        p += 1 if p == 2 else 2
    if temp > 1:
        s *= (1 + temp)
    return s

def count_solutions(A):
    if A == 1:
        return 1  # x = 1
    count = 0
    limit = int(math.isqrt(A))
    for d in range(1, limit + 1):
        if A % d == 0:
            x1 = d - 1
            if x1 > 0 and divisor_sum(x1) == A:
                count += 1
            x2 = A // d - 1
            if x2 != x1 and x2 > 0 and divisor_sum(x2) == A:
                count += 1
    return count

def main():
    A = int(sys.stdin.readline().strip())
    print(count_solutions(A))

if __name__ == "__main__":
    main()

